"""Tests for source-root path expansion."""

from pathlib import Path

import pytest

from pylint.config.argument import _paths_csv_transformer


@pytest.mark.parametrize(
    "pattern",
    ["src/*", "src/package?", "src/package[12]", "**/package?"],
)
def test_source_roots_glob(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, pattern: str
) -> None:
    monkeypatch.chdir(tmp_path)
    for name in ("package1", "package2"):
        (tmp_path / "src" / name).mkdir(parents=True)
    assert set(_paths_csv_transformer(pattern)) == {
        str(Path("src/package1")),
        str(Path("src/package2")),
    }


